/**
 * Public data for the Quant Arena showcase pages.
 *
 * The JSON files are generated by scripts/sync-quant-arena-data.mjs from the
 * paper tables; edit the source tables and re-run the script instead of
 * editing them by hand.
 */

import families from "../data/quant-arena/families.json";
import leaderboard from "../data/quant-arena/leaderboard.json";
import maxEffort from "../data/quant-arena/max-effort.json";

// The live Arena moves to its official domain later; keep the link here only.
export const ARENA_URL = "https://dev.quant.xiaoaojianghu.fun/arena";

export const KEPLER_NOTE =
  "Kepler-1 is a proprietary strategy developed by Einsia AI; its construction is not disclosed.";

export const tracks = [
  {
    id: "iterative",
    name: "Iterative research",
    description:
      "The model researches on 2022–2023 with bounded feedback on its candidates, then commits one strategy.",
  },
  {
    id: "oneshot",
    name: "One-shot generation",
    description: "The model writes one strategy in a single pass, without research-window feedback.",
  },
];

export const effortOrder = ["None", "Low", "Medium", "High", "XHigh", "Max"];

// Same opacity ramp as the PPTBench leaderboard: lighter means less effort.
export const effortOpacity = {
  None: 0.34,
  Low: 0.45,
  Medium: 0.58,
  High: 0.7,
  XHigh: 0.84,
  Max: 1,
};

export const familyColor = Object.fromEntries(families.map((family) => [family.model, family.color]));
export const KEPLER_COLOR = "#1f2937";

export const kepler = leaderboard.find((row) => row.track === "reference");
export const modelRows = leaderboard.filter((row) => row.track !== "reference");

/** Every effort of every model, grouped by model and ordered by the model's best score. */
export const groupsFor = (track) => {
  const rows = modelRows.filter((row) => row.track === track);
  return families
    .map((family) => ({
      ...family,
      rows: rows
        .filter((row) => row.model === family.model)
        .sort((a, b) => effortOrder.indexOf(a.effort) - effortOrder.indexOf(b.effort)),
    }))
    .filter((group) => group.rows.length > 0)
    .map((group) => ({ ...group, best: Math.max(...group.rows.map((row) => row.total)) }))
    .sort((a, b) => b.best - a.best);
};

const mean = (values) => values.reduce((sum, value) => sum + value, 0) / values.length;

/** One row per model at its highest available effort, with both settings side by side. */
export const maxEffortRows = families
  .map((family) => {
    const pick = (track) => maxEffort.find((row) => row.model === family.model && row.track === track);
    return { ...family, iterative: pick("iterative"), oneshot: pick("oneshot") };
  })
  .sort((a, b) => b.iterative.total - a.iterative.total);

export const maxEffortMeans = {
  iterative: mean(maxEffortRows.map((row) => row.iterative.total)),
  oneshot: mean(maxEffortRows.map((row) => row.oneshot.total)),
};

// Excess is ARR minus the equal-weight market ARR; the max-effort table keeps
// four decimals, so recover the market return from it.
const unrounded = maxEffort.filter((row) => row.arr != null && row.excess != null);
export const marketArr = mean(unrounded.map((row) => row.arr - row.excess / 100));

// Normalise -0 so rounded zeros never print with a minus sign.
const fixed = (value, digits) => (Number(value.toFixed(digits)) || 0).toFixed(digits).replace("-", "−");

export const formatScore = (value) => (value == null ? "—" : value.toFixed(2));
export const formatPercent = (value, digits = 1) =>
  value == null ? "—" : `${fixed(value * 100, digits)}%`;
export const formatSigned = (value, digits = 1) =>
  value == null ? "—" : `${value > 0 ? "+" : ""}${fixed(value, digits)}`;
export const formatNumber = (value, digits) => (value == null ? "—" : fixed(value, digits));
